#include <openssl/rand.h>

class SecureStorage {
private:
    std::map<std::string, std::string> encrypted_fields_;
    unsigned char key_[32];

public:
    SecureStorage() {
        RAND_bytes(key_, 32);
    }

    std::string encrypt(const std::string& plaintext) {
        unsigned char iv[12];
        RAND_bytes(iv, 12);
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key_, iv);
        std::vector<unsigned char> ciphertext(plaintext.size() + 16);
        int len = 0;
        EVP_EncryptUpdate(ctx, ciphertext.data(), &len, 
            reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.size());
        int ct_len = len;
        EVP_EncryptFinal_ex(ctx, ciphertext.data() + len, &len);
        ct_len += len;
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(ctx);
        std::string result(reinterpret_cast<char*>(iv), 12);
        result.append(reinterpret_cast<char*>(tag), 16);
        result.append(reinterpret_cast<char*>(ciphertext.data()), ct_len);
        return result;
    }

    std::string decrypt(const std::string& blob) {
        if (blob.size() < 28) return "";
        const unsigned char* iv = reinterpret_cast<const unsigned char*>(blob.data());
        const unsigned char* tag = reinterpret_cast<const unsigned char*>(blob.data() + 12);
        const unsigned char* ct = reinterpret_cast<const unsigned char*>(blob.data() + 28);
        int ct_len = blob.size() - 28;
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key_, iv);
        std::vector<unsigned char> plaintext(ct_len);
        int len = 0;
        EVP_DecryptUpdate(ctx, plaintext.data(), &len, ct, ct_len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, const_cast<unsigned char*>(tag));
        int ret = EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &len);
        EVP_CIPHER_CTX_free(ctx);
        if (ret <= 0) return "";
        return std::string(reinterpret_cast<char*>(plaintext.data()), plaintext.size());
    }

    void store(const std::string& key, const std::string& value) {
        encrypted_fields_[key] = encrypt(value);
    }

    std::string retrieve(const std::string& key) {
        auto it = encrypted_fields_.find(key);
        if (it == encrypted_fields_.end()) return "";
        return decrypt(it->second);
    }
};

class TemplateEngine {
private:
    std::map<std::string, std::function<std::string(const std::string&)>> functions_;
    std::map<std::string, std::string> variables_;

    std::string evaluate_expression(const std::string& expr) {
        // Check for function calls: func_name(arg)
        std::regex func_regex(R"((\w+)\(([^)]*)\))");
        std::smatch match;
        if (std::regex_match(expr, match, func_regex)) {
            std::string func_name = match[1].str();
            std::string arg = match[2].str();
            auto it = functions_.find(func_name);
            if (it != functions_.end()) {
                // Recursively resolve the argument
                std::string resolved_arg = resolve_template(arg);
                return it->second(resolved_arg);
            }
        }
        // Variable lookup
        auto it = variables_.find(expr);
        if (it != variables_.end()) return it->second;
        return "";
    }

public:
    void register_function(const std::string& name, 
                          std::function<std::string(const std::string&)> func) {
        functions_[name] = func;
    }

    void set_variable(const std::string& name, const std::string& value) {
        variables_[name] = value;
    }

    std::string resolve_template(const std::string& tmpl) {
        std::string result;
        size_t pos = 0;
        while (pos < tmpl.size()) {
            size_t start = tmpl.find("${", pos);
            if (start == std::string::npos) {
                result += tmpl.substr(pos);
                break;
            }
            result += tmpl.substr(pos, start - pos);
            size_t end = tmpl.find("}", start + 2);
            if (end == std::string::npos) {
                result += tmpl.substr(start);
                break;
            }
            std::string expr = tmpl.substr(start + 2, end - start - 2);
            result += evaluate_expression(expr);
            pos = end + 1;
        }
        return result;
    }
};

class EmailService {
private:
    SecureStorage storage_;
    TemplateEngine engine_;

    std::string format_header(const std::string& key, const std::string& value) {
        return key + ": " + value + "\r\n";
    }

public:
    EmailService() {
        // Register safe utility functions
        engine_.register_function("upper", [](const std::string& s) {
            std::string result = s;
            for (auto& c : result) c = toupper(c);
            return result;
        });
        engine_.register_function("lower", [](const std::string& s) {
            std::string result = s;
            for (auto& c : result) c = tolower(c);
            return result;
        });
        engine_.register_function("trim", [](const std::string& s) {
            size_t start = s.find_first_not_of(" \t\r\n");
            size_t end = s.find_last_not_of(" \t\r\n");
            if (start == std::string::npos) return std::string("");
            return s.substr(start, end - start + 1);
        });
        // Storage access function for template personalization
        engine_.register_function("lookup", [this](const std::string& key) {
            return storage_.retrieve(key);
        });
        // System command for generating message IDs
        engine_.register_function("msgid", [](const std::string& domain) {
            std::string cmd = "echo $(date +%s).$$@" + domain;
            char buffer[256];
            std::string result;
            FILE* pipe = popen(cmd.c_str(), "r");
            if (pipe) {
                while (fgets(buffer, sizeof(buffer), pipe)) result += buffer;
                pclose(pipe);
            }
            if (!result.empty() && result.back() == '\n') result.pop_back();
            return result;
        });
    }

    void store_recipient_data(const std::string& email, const std::string& name) {
        storage_.store("recipient_" + email, name);
    }

    std::string compose_email(const std::string& to, const std::string& subject_template,
                             const std::string& body_template, const std::string& domain) {
        engine_.set_variable("to", to);
        engine_.set_variable("domain", domain);

        std::string resolved_subject = engine_.resolve_template(subject_template);
        std::string resolved_body = engine_.resolve_template(body_template);

        // Generate message ID using domain
        std::string msg_id = engine_.resolve_template("${msgid(" + domain + ")}");

        std::string email_msg;
        email_msg += format_header("To", to);
        email_msg += format_header("Subject", resolved_subject);
        email_msg += format_header("Message-ID", "<" + msg_id + ">");
        email_msg += format_header("Content-Type", "text/plain; charset=utf-8");
        email_msg += "\r\n";
        email_msg += resolved_body;

        return email_msg;
    }
};

int main() {
    EmailService service;
    service.store_recipient_data("alice@example.com", "Alice Johnson");

    std::string to = "alice@example.com";
    std::string subject = "Hello ${lookup(recipient_alice@example.com)}";
    std::string body = "Dear ${lookup(recipient_alice@example.com)},\n\nWelcome!";
    std::string domain = "example.com";

    std::string email = service.compose_email(to, subject, body, domain);
    std::cout << email << std::endl;

    return 0;
}
